namespace letswifi\credential;

use DateTimeInterface;
use DomainException;
use fyrkat\openssl\X509;
use letswifi\profile\Realm;

/**
 * A credential issued from a client-provided CSR.
 *
 * The private key was generated by the client and never touched the server,
 * so unlike CertificateCredential this credential has no PKCS12 payload;
 * the payload is the signed certificate together with its issuer chain.
 *
 * @extends Credential<array{x509:string,chain:array<string>}>
 */
class CsrCredential extends Credential
{
	public readonly DateTimeInterface $expiry;

	public readonly DateTimeInterface $issued;

	/**
	 * @param array{x509:string,chain:array<string>} $payload
	 */
	public function __construct(
		string $credentialId,
		string $userId,
		?string $clientId,
		?string $grantSid,
		?string $ip,
		?string $userAgent,
		Realm $realm,
		X509 $userCert,
		private readonly array $payload,
	) {
		parent::__construct(
			credentialId: $credentialId,
			userId: $userId,
			clientId: $clientId,
			grantSid: $grantSid,
			ip: $ip,
			userAgent: $userAgent,
			realm: $realm,
		);

		$this->issued = $userCert->getValidFrom();
		$this->expiry = $userCert->getValidTo();
	}

	/**
	 * @return array{x509:string,chain:array<string>}
	 */
	public function getPayload(): array
	{
		return $this->payload;
	}

	/**
	 * A CSR credential has no private key, so it can never produce a PKCS12.
	 */
	public function getPKCS12(): never
	{
		throw new DomainException( 'Cannot create PKCS12 because the private key is on the client side' );
	}

	public function getExpiry(): DateTimeInterface
	{
		return $this->expiry;
	}

	public function getIssued(): DateTimeInterface
	{
		return $this->issued;
	}

	public function getRevoked(): ?DateTimeInterface
	{
		return null;
	}

	public function isRevoked(): bool
	{
		return false;
	}
}
